INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT143-S3-Q4$batch08$, 143, 3, 4, $batch08$Most Strongly Supported$batch08$, $batch08$The size of the spleen is a good indicator of how healthy a bird is: sickly birds generally have significantly smaller spleens than healthy birds. Researchers found that, in general, birds that had been killed by predators had substantially smaller spleens than birds killed accidentally.$batch08$, $batch08$Which one of the following is most strongly supported by the information above?$batch08$, $batch08$D$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=143 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Predators are unable to kill healthy birds.$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Most birds with smaller than average spleens are killed by predators.$batch08$, $batch08$Reversed$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Predators can sense whether a bird is sick.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Sickly birds are more likely than healthy birds to be killed by predators.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$Small spleen size is one of the main causes of sickness in birds.$batch08$, $batch08$Reversed$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Spleen size indicates health: sick birds generally have much smaller spleens. Birds killed by predators had much smaller spleens than birds killed by accidents.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. Small spleen means sickly. Predator victims had small spleens. So predator victims were disproportionately sickly. Accidents are a rough sample of the whole population, so sickly birds are overrepresented among the ones predators take.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Sickly birds are more likely to fall to predators.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$"Generally" and "substantially smaller" describe tendencies. Predators surely catch some healthy birds.$batch08$), ($batch08$B$batch08$, $batch08$We know predator victims tend to have small spleens. That doesn't mean most small-spleen birds end up killed by predators.$batch08$), ($batch08$C$batch08$, $batch08$Maybe predators sense sickness, or maybe sick birds are just slower. The passage doesn't say how it happens.$batch08$), ($batch08$D$batch08$, $batch08$Predator victims skew toward small spleens, and small spleens mark sick birds. "More likely" is just as strong as the data.$batch08$), ($batch08$E$batch08$, $batch08$Spleen size *indicates* sickness. Nothing says it causes it.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT143-S3-Q4$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
